/* La carrera del sapo: renders the story from window.STORY_DATA (generated by tools/build_story.py). */
(function () {
  "use strict";

  const DATA = window.STORY_DATA;
  const SVG_NS = "http://www.w3.org/2000/svg";
  const REDUCED_MOTION = (function () {
    try {
      return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    } catch (error) {
      return false;
    }
  })();

  // Series color per run id. Unknown runs fall back to the palette in order.
  const SERIES_STYLE = {
    run_2m: { color: "var(--muted)", dashed: true },
    run_px_5m: { color: "var(--c-plum)" },
    run_px_5m_safe: { color: "var(--c-slate)" },
    run_px_5m_r3: { color: "var(--sun)" },
    run_px_5m_r4: { color: "var(--road)" },
    run_px_5m_r5: { color: "var(--river)" },
    run_px_5m_r3_seed43_mac: { color: "var(--c-grass)" },
  };
  const FALLBACK_COLORS = ["var(--c-plum)", "var(--c-slate)", "var(--c-grass)", "var(--sun)"];
  const MAX_STEP = 5000000;

  const LOOP_CAPTIONS = [
    "El entorno recibe una acción del sapo y devuelve la nueva observación, la recompensa y si el episodio terminó.",
    "ε-greedy: con probabilidad ε la acción es al azar; si no, la de mayor valor Q. ε baja con los pasos.",
    "El buffer guarda la transición (s, a, r, s′, fin). Cuando está lleno, reemplaza la más antigua.",
    "Un minibatch se muestrea al azar del buffer. Así los pasos seguidos, muy parecidos, no dominan el aprendizaje.",
    "Objetivo de Bellman: y = r + γ (1 − fin) max Q de la red objetivo. La red objetivo no recibe gradiente.",
    "La pérdida de Huber compara Q(s, a) con y. Para errores grandes crece de forma lineal, no al cuadrado.",
    "Un paso de gradiente ajusta la red en línea. Cada cierto número de pasos, la red objetivo copia sus pesos.",
  ];

  // ---------- small helpers ----------

  function el(tag, props, children) {
    const node = document.createElement(tag);
    if (props) {
      Object.keys(props).forEach((key) => {
        const value = props[key];
        if (value === null || value === undefined || value === false) return;
        if (key === "class") node.className = value;
        else if (key === "text") node.textContent = value;
        else if (key === "style") node.setAttribute("style", value);
        else node.setAttribute(key, value === true ? "" : String(value));
      });
    }
    (children || []).forEach((child) => {
      if (child === null || child === undefined) return;
      node.append(typeof child === "string" ? document.createTextNode(child) : child);
    });
    return node;
  }

  function clear(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  function fmt(value, digits) {
    if (value === null || value === undefined || Number.isNaN(value)) return "—";
    return Number(value).toFixed(digits).replace(".", ",");
  }

  function fmtInt(value) {
    if (value === null || value === undefined) return "—";
    return String(Math.round(value)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  }

  function pct(fraction) {
    return `${Math.round(fraction * 100)} %`;
  }

  function svgEl(tag, attrs, text) {
    const node = document.createElementNS(SVG_NS, tag);
    Object.keys(attrs || {}).forEach((key) => node.setAttribute(key, String(attrs[key])));
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function runById(id) {
    return DATA.runs.find((run) => run.id === id) || null;
  }

  function pixelsOrRam(run) {
    return run.settings.observation && run.settings.observation.indexOf("píxeles") === 0
      ? "Píxeles"
      : "RAM";
  }

  // ---------- hero ----------

  function heroFigure(row, title, caption, alt) {
    return el("figure", null, [
      el("span", { class: "fig-title", text: title }),
      el("img", {
        src: row.gif,
        alt: alt,
        width: 300,
        height: 300,
        loading: "eager",
        decoding: "async",
      }),
      el("figcaption", null, [
        el("p", { class: "fig-stats", text: caption }),
      ]),
    ]);
  }

  function renderHero() {
    const host = document.getElementById("hero-pair");
    clear(host);
    const hero = DATA.hero;
    if (!hero || !hero.checkpoint || !hero.random || !hero.checkpoint.gif || !hero.random.gif) {
      host.append(el("p", { text: "Faltan datos de los GIF. Ejecuta tools/build_story.py." }));
      return;
    }
    const random = hero.random;
    const best = hero.checkpoint;
    const bestRun = runById(hero.run_id);
    const episodes = best.episodes || 20;
    host.append(
      heroFigure(
        random,
        "Política aleatoria",
        `Puntaje ${fmt(random.score_mean, 1)} ± ${fmt(random.score_std, 1)} · ${random.episodes} episodios`,
        "GIF de la política aleatoria, primer episodio de evaluación"
      ),
      heroFigure(
        best,
        `${hero.run_label} · ${best.title} pasos`,
        `Puntaje ${fmt(best.score_mean, 1)} ± ${fmt(best.score_std, 1)} · ${pct(best.medals.frog_home)} de episodios con casa`,
        `GIF del mejor checkpoint, ${best.title} pasos, primer episodio de evaluación`
      ),
      el("p", { class: "hero-note", text:
        `Los GIF muestran el primer episodio de evaluación; las cifras son la media de ${episodes} episodios. ` +
        `El checkpoint se eligió por ${hero.reason}. ` +
        (bestRun ? `Corrida ${bestRun.label} (${pixelsOrRam(bestRun)}).` : "") }),
    );
  }

  // ---------- medal race ----------

  const race = {
    run: null,
    index: 0,
    timer: null,
    ladderRefs: [],
  };

  function setRunPicked(runIndex) {
    const buttons = document.querySelectorAll("#run-picker button");
    buttons.forEach((button, i) => button.setAttribute("aria-pressed", String(i === runIndex)));
  }

  function renderRunPicker() {
    const picker = document.getElementById("run-picker");
    clear(picker);
    DATA.runs.forEach((run, i) => {
      const buffer = run.settings.buffer_size ? `buffer ${fmtInt(run.settings.buffer_size)}` : "buffer sin registro";
      picker.append(
        el("button", {
          type: "button",
          "aria-pressed": "false",
          "data-run-index": i,
          class: "run-button",
        }, [
          run.label,
          el("span", { class: "run-sub", text: `${pixelsOrRam(run)} · ${buffer}${run.status === "partial" ? " · parcial" : ""}` }),
        ])
      );
    });
    picker.addEventListener("click", (event) => {
      const button = event.target.closest("button[data-run-index]");
      if (!button) return;
      selectRun(Number(button.getAttribute("data-run-index")));
    });
  }

  function buildLadder(run) {
    const list = document.getElementById("ladder");
    clear(list);
    race.ladderRefs = [];
    DATA.medal_ladder.forEach((medal) => {
      const name = el("span", { class: "name" }, [
        medal.name,
        el("span", { class: "threshold", text: medal.threshold }),
      ]);
      const earnedChip = el("span", { class: "chip", text: "obtenida", hidden: true });
      name.append(earnedChip);
      const fill = el("span", { class: "bar-fill" });
      const pctLabel = el("span", { class: "pct" });
      const item = el("li", { "data-medal": medal.key }, [
        el("span", { class: "medal", "aria-hidden": "true", text: medal.emoji }),
        name,
        pctLabel,
        el("span", { class: "bar", role: "presentation" }, [fill]),
      ]);
      list.append(item);
      race.ladderRefs.push({ key: medal.key, item, fill, pctLabel, earnedChip });
    });
  }

  function updateLadder(row) {
    race.ladderRefs.forEach((ref) => {
      const value = row.medals[ref.key] || 0;
      const earned = value >= 0.5;
      ref.item.classList.toggle("is-earned", earned);
      ref.fill.style.setProperty("--w", `${Math.round(value * 100)}%`);
      ref.fill.style.width = `${Math.round(value * 100)}%`;
      ref.pctLabel.textContent = pct(value);
      ref.earnedChip.hidden = !earned;
      ref.item.setAttribute("aria-label", `${ref.key}: ${pct(value)}${earned ? ", obtenida" : ""}`);
    });
  }

  function renderStats(row) {
    const stats = document.getElementById("race-stats");
    clear(stats);
    const items = [
      ["Puntaje (media ± desv.)", `${fmt(row.score_mean, 1)} ± ${fmt(row.score_std, 1)}`],
      ["Episodios", String(row.episodes)],
      ["Fila máxima (media / máx.)", `${fmt(row.max_rows_mean, 1)} / ${row.max_rows_max}`],
      ["Casas (media / máx.)", `${fmt(row.homes_mean, 2)} / ${row.homes_max}`],
    ];
    items.forEach(([label, value]) => {
      stats.append(el("div", null, [el("dt", { text: label }), el("dd", { text: value })]));
    });
  }

  function renderTicks(run) {
    const list = document.getElementById("tl-ticks");
    clear(list);
    run.rows.forEach((row, i) => {
      list.append(el("li", null, [
        el("button", {
          type: "button",
          "aria-pressed": "false",
          "data-index": i,
          "aria-label": `Punto de control ${row.title}`,
          text: row.title,
        }),
      ]));
    });
  }

  function animateFigure() {
    const view = document.getElementById("race-view");
    if (REDUCED_MOTION || typeof view.animate !== "function") return;
    view.animate([{ opacity: 0.35 }, { opacity: 1 }], { duration: 260, easing: "ease-out" });
  }

  function setCheckpoint(index, animate) {
    const run = race.run;
    if (!run) return;
    const max = run.rows.length - 1;
    race.index = Math.max(0, Math.min(index, max));
    const row = run.rows[race.index];

    const range = document.getElementById("tl-range");
    range.max = String(max);
    range.value = String(race.index);
    range.setAttribute("aria-valuetext", `${row.title}${row.step === null ? "" : " pasos"}`);

    document.querySelectorAll("#tl-ticks button").forEach((button, i) => {
      button.setAttribute("aria-pressed", String(i === race.index));
    });

    const img = document.getElementById("race-gif");
    const caption = document.getElementById("race-caption");
    if (row.gif) {
      img.hidden = false;
      img.setAttribute("src", row.gif);
      img.setAttribute("alt", `${run.label}, ${row.title}: primer episodio de evaluación`);
    } else {
      img.hidden = true;
      img.removeAttribute("src");
    }
    caption.textContent = `${run.label} · ${row.title}${row.step === null ? "" : " pasos"} · primer episodio de evaluación`;
    if (animate) animateFigure();

    renderStats(row);
    updateLadder(row);
  }

  function selectRun(index) {
    stopPlaying();
    race.run = DATA.runs[index];
    if (!race.run) return;
    setRunPicked(index);
    renderTicks(race.run);
    buildLadder(race.run);
    const runNote = document.getElementById("race-run-note");
    runNote.textContent = [race.run.change, ...race.run.notes].filter(Boolean).join(" ");
    const homeDetection = DATA.home_detection;
    document.getElementById("home-note").textContent =
      homeDetection && homeDetection.status === "verified" ? homeDetection.evidence : "";
    setCheckpoint(race.run.rows.length - 1, false);
  }

  function stopPlaying() {
    if (race.timer !== null) {
      window.clearInterval(race.timer);
      race.timer = null;
    }
    const play = document.getElementById("tl-play");
    play.setAttribute("aria-pressed", "false");
    play.textContent = "Reproducir";
  }

  function togglePlaying() {
    const play = document.getElementById("tl-play");
    if (race.timer !== null) {
      stopPlaying();
      return;
    }
    if (!race.run) return;
    if (race.index >= race.run.rows.length - 1) setCheckpoint(0, false);
    play.setAttribute("aria-pressed", "true");
    play.textContent = "Pausar";
    race.timer = window.setInterval(() => {
      if (race.index >= race.run.rows.length - 1) {
        stopPlaying();
        return;
      }
      setCheckpoint(race.index + 1, true);
    }, 1600);
  }

  function initRace() {
    renderRunPicker();
    document.getElementById("tl-ticks").addEventListener("click", (event) => {
      const button = event.target.closest("button[data-index]");
      if (!button) return;
      stopPlaying();
      setCheckpoint(Number(button.getAttribute("data-index")), true);
    });
    const heroIndex = Math.max(0, DATA.runs.findIndex((run) => run.id === (DATA.hero && DATA.hero.run_id)));
    document.getElementById("tl-range").addEventListener("input", (event) => {
      stopPlaying();
      setCheckpoint(Number(event.target.value), true);
    });
    document.getElementById("tl-prev").addEventListener("click", () => {
      stopPlaying();
      setCheckpoint(race.index - 1, true);
    });
    document.getElementById("tl-next").addEventListener("click", () => {
      stopPlaying();
      setCheckpoint(race.index + 1, true);
    });
    document.getElementById("tl-play").addEventListener("click", togglePlaying);
    selectRun(heroIndex);
  }

  // ---------- chart ----------

  const chartState = { metric: "home", hidden: new Set() };

  function seriesColor(run, index) {
    const style = SERIES_STYLE[run.id];
    return style ? style.color : FALLBACK_COLORS[index % FALLBACK_COLORS.length];
  }

  function renderLegend() {
    const legend = document.getElementById("legend");
    clear(legend);
    DATA.runs.forEach((run, i) => {
      if (!run.rows.some((row) => row.step !== null)) return;
      const style = SERIES_STYLE[run.id] || {};
      const swatch = el("span", { class: `swatch${style.dashed ? " is-dashed" : ""}`, "aria-hidden": "true" });
      swatch.style.setProperty("--c", seriesColor(run, i));
      const visible = !chartState.hidden.has(run.id);
      legend.append(el("button", {
        type: "button",
        "aria-pressed": String(visible),
        "data-run-id": run.id,
        title: run.change,
      }, [swatch, run.label]));
    });
    legend.onclick = (event) => {
      const button = event.target.closest("button[data-run-id]");
      if (!button) return;
      const id = button.getAttribute("data-run-id");
      if (chartState.hidden.has(id)) chartState.hidden.delete(id);
      else chartState.hidden.add(id);
      button.setAttribute("aria-pressed", String(!chartState.hidden.has(id)));
      const group = document.querySelector(`#chart g[data-run-id="${id}"]`);
      if (group) group.classList.toggle("series-hidden", chartState.hidden.has(id));
    };
  }

  function renderChart() {
    const svg = document.getElementById("chart");
    const W = 720;
    const H = 380;
    const L = 64;
    const R = 20;
    const T = 16;
    const B = 52;
    const plotW = W - L - R;
    const plotH = H - T - B;
    const isHome = chartState.metric === "home";
    const yMax = isHome ? 100 : 12;
    const yTicks = isHome ? [0, 25, 50, 75, 100] : [0, 3, 6, 9, 12];
    const x = (step) => L + (step / MAX_STEP) * plotW;
    const y = (value) => T + plotH - (value / yMax) * plotH;

    Array.from(svg.querySelectorAll("g, text, line, polyline")).forEach((node) => node.remove());
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);

    const title = svg.querySelector("title");
    title.textContent = isHome
      ? "Porcentaje de episodios con casa por punto de control"
      : "Fila máxima media por punto de control";
    svg.querySelector("desc").textContent = isHome
      ? "Líneas por corrida con el porcentaje de episodios que llegan a casa frente a los pasos de entrenamiento. La corrida RAM aparece en línea punteada."
      : "Líneas por corrida con la fila máxima media por episodio frente a los pasos de entrenamiento. La fila 12 es la casa.";

    yTicks.forEach((value) => {
      svg.append(svgEl("line", { x1: L, x2: W - R, y1: y(value), y2: y(value), class: "grid" }));
      svg.append(svgEl("text", { x: L - 10, y: y(value) + 4, "text-anchor": "end", class: "tick" }, isHome ? `${value} %` : String(value)));
    });
    svg.append(svgEl("line", { x1: L, x2: L, y1: T, y2: T + plotH, class: "axis" }));
    svg.append(svgEl("line", { x1: L, x2: W - R, y1: T + plotH, y2: T + plotH, class: "axis" }));

    const stepTicks = [0, 1000000, 2000000, 3000000, 4000000, 5000000];
    stepTicks.forEach((step) => {
      const label = step === 0 ? "0" : `${step / 1000000} M`;
      svg.append(svgEl("text", { x: x(step), y: T + plotH + 22, "text-anchor": "middle", class: "tick" }, label));
    });
    svg.append(svgEl("text", { x: L + plotW / 2, y: H - 8, "text-anchor": "middle", class: "axis-title" }, "Pasos de entrenamiento"));
    svg.append(svgEl("text", {
      x: 14,
      y: T + plotH / 2,
      "text-anchor": "middle",
      transform: `rotate(-90 14 ${T + plotH / 2})`,
      class: "axis-title",
    }, isHome ? "Episodios con casa" : "Fila máxima media"));

    DATA.runs.forEach((run, i) => {
      const points = run.rows.filter((row) => row.step !== null).sort((a, b) => a.step - b.step);
      if (points.length === 0) return;
      const style = SERIES_STYLE[run.id] || {};
      const color = seriesColor(run, i);
      const values = points.map((row) => (isHome ? row.medals.frog_home * 100 : row.max_rows_mean));
      const group = svgEl("g", { "data-run-id": run.id, class: chartState.hidden.has(run.id) ? "series-hidden" : "" });
      group.style.setProperty("--c", color);
      const line = svgEl("polyline", {
        points: points.map((row, j) => `${x(row.step)},${y(values[j])}`).join(" "),
        class: `series${style.dashed ? " is-dashed" : ""}`,
      });
      group.append(line);
      points.forEach((row, j) => {
        const dot = svgEl("circle", { cx: x(row.step), cy: y(values[j]), r: 4.5, class: "dot" });
        dot.append(svgEl("title", {}, `${run.label}, ${row.title} pasos: ${isHome ? pct(row.medals.frog_home) + " de episodios con casa" : fmt(row.max_rows_mean, 1) + " de fila máxima"}`));
        group.append(dot);
      });
      svg.append(group);
    });
  }

  function renderMetricButtons() {
    const home = document.getElementById("metric-home");
    const row = document.getElementById("metric-row");
    const apply = (metric) => {
      chartState.metric = metric;
      home.setAttribute("aria-pressed", String(metric === "home"));
      row.setAttribute("aria-pressed", String(metric === "row"));
      renderChart();
    };
    home.addEventListener("click", () => apply("home"));
    row.addEventListener("click", () => apply("row"));
  }

  function renderCompare() {
    const body = document.getElementById("compare-body");
    clear(body);
    DATA.runs.forEach((run) => {
      const best = (DATA.best_by_run || {})[run.id] || {};
      const homeText = best.frog_home > 0 ? `${pct(best.frog_home)} (${best.frog_home_title})` : "0 %";
      const scoreText = best.score_mean === null || best.score_mean === undefined
        ? "—"
        : `${fmt(best.score_mean, 1)} (${best.score_title})`;
      const sps = run.settings.steps_per_second;
      const label = el("span", null, [run.label, run.status === "partial" ? el("span", { class: "chip", text: "parcial" }) : null]);
      body.append(el("tr", null, [
        el("td", null, [label]),
        el("td", { text: run.change }),
        el("td", { class: "num", text: scoreText }),
        el("td", { class: "num", text: homeText }),
        el("td", { class: "num", text: sps ? fmt(sps, 1) : "sin registro" }),
      ]));
    });
  }

  // ---------- lessons (numbers read from data.js) ----------

  function lessonRows(runId) {
    const run = runById(runId);
    return run ? run.rows : [];
  }

  function renderLessons() {
    const list = document.getElementById("lesson-list");
    clear(list);
    const bench = DATA.benchmark || {};
    const train = bench.train_steps_per_second || {};
    const slower = train.cpu && train.cuda ? Math.round((1 - train.cuda / train.cpu) * 100) : null;
    const pilot = DATA.pilot_h2 || {};
    const ratio = pilot.mixed_steps_per_second && pilot.all_cpu_steps_per_second
      ? fmt(pilot.mixed_steps_per_second / pilot.all_cpu_steps_per_second, 1)
      : null;
    const memory = DATA.memory || {};
    const ram = lessonRows("run_2m");
    const at250 = ram.find((row) => row.step === 250000);
    const at500 = ram.find((row) => row.step === 500000);

    const items = [
      [
        "Mide antes de optimizar la infraestructura.",
        train.cpu && train.cuda
          ? `Para la red pequeña de la entrega, la GPU fue ${slower} % más lenta: ${fmt(train.cuda, 1)} pasos/s frente a ${fmt(train.cpu, 1)} en CPU. Se midió antes de decidir.`
          : "Para la red pequeña de la entrega, medir fue más útil que suponer.",
      ],
      [
        "La GPU sí paga con una CNN.",
        ratio
          ? `En la prueba de 100 000 pasos, el modo mixto (CPU para los entornos, GPU para la CNN) hizo ${fmt(pilot.mixed_steps_per_second, 1)} pasos/s; todo en CPU, ${fmt(pilot.all_cpu_steps_per_second, 1)}. Son ${ratio} veces más.`
          : "Con una CNN, el modo mixto de CPU y GPU fue varias veces más rápido que todo en CPU.",
      ],
      [
        "Presupuesta la memoria contra la RAM libre de hoy.",
        memory.stacked_gb
          ? `Con 200 000 transiciones, guardar dos observaciones completas pedía ${fmt(memory.stacked_gb, 1)} GB; con cuadros compartidos, ${fmt(memory.frame_gb, 2)} GB. La corrida 1 se detuvo por falta de memoria en 4,6 M de pasos.`
          : "Guardar observaciones completas en el buffer consume mucha memoria.",
      ],
      [
        "Guarda con frecuencia.",
        "La corrida 1 tenía checkpoints solo hasta 3 M. Los pesos de 3 M a 4,6 M se perdieron con el proceso y no se pudieron recuperar.",
      ],
      [
        "El puntaje no es habilidad: mira las medallas.",
        at250 && at500
          ? `En la RAM de la entrega, el puntaje medio bajó de ${fmt(at250.score_mean, 1)} a ${fmt(at500.score_mean, 1)} entre 250 000 y 500 000 pasos, pero la medalla de mitad del río subió de ${pct(at250.medals.mid_river)} a ${pct(at500.medals.mid_river)}.`
          : "El puntaje medio puede bajar mientras la medalla de mitad del río sube.",
      ],
      [
        "El recorte de recompensa escondió el +55.",
        "Con recorte por signo, llegar a casa (+55) y avanzar una fila (+1) llegaban igual, como +1. El agente no podía aprender que casa vale 55 veces más. Por eso se probó una escala de 0,1 en la corrida 3.",
      ],
    ];
    items.forEach(([lead, body]) => {
      list.append(el("li", null, [
        el("div", null, [el("strong", { text: lead }), el("span", { class: "lesson-body", text: body })]),
      ]));
    });
  }

  // ---------- loop diagram ----------

  function initLoop() {
    const nodes = Array.from(document.querySelectorAll(".loop .step"));
    const caption = document.getElementById("loop-caption");
    const play = document.getElementById("loop-play");
    let index = 0;
    let timer = null;

    function show(i) {
      index = ((i % nodes.length) + nodes.length) % nodes.length;
      nodes.forEach((node, j) => {
        node.classList.toggle("is-active", j === index);
        node.classList.toggle("is-done", j < index);
      });
      caption.textContent = `Paso ${index + 1} de ${nodes.length}. ${LOOP_CAPTIONS[index]}`;
    }

    function stop() {
      if (timer !== null) window.clearInterval(timer);
      timer = null;
      play.setAttribute("aria-pressed", "false");
      play.textContent = "Reproducir";
    }

    function start() {
      play.setAttribute("aria-pressed", "true");
      play.textContent = "Pausar";
      timer = window.setInterval(() => show(index + 1), 1600);
    }

    document.getElementById("loop-prev").addEventListener("click", () => { stop(); show(index - 1); });
    document.getElementById("loop-next").addEventListener("click", () => { stop(); show(index + 1); });
    play.addEventListener("click", () => (timer === null ? start() : stop()));
    show(0);
  }

  // ---------- theme ----------

  function initTheme() {
    const button = document.getElementById("theme-toggle");
    const root = document.documentElement;
    const systemDark = (() => {
      try {
        return window.matchMedia("(prefers-color-scheme: dark)").matches;
      } catch (error) {
        return false;
      }
    })();
    const current = () => root.getAttribute("data-theme") || (systemDark ? "dark" : "light");
    const sync = () => button.setAttribute("aria-pressed", String(current() === "dark"));
    sync();
    button.addEventListener("click", () => {
      const next = current() === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try {
        window.localStorage.setItem("historia-tema", next);
      } catch (error) {
        /* storage blocked: the choice lasts for this page view only */
      }
      sync();
    });
  }

  // ---------- start ----------

  function start() {
    if (!DATA || !Array.isArray(DATA.runs)) {
      const host = document.getElementById("hero-pair");
      host.textContent = "No se encontraron los datos (data.js). Ejecuta tools/build_story.py.";
      return;
    }
    initTheme();
    renderHero();
    initRace();
    renderLegend();
    renderMetricButtons();
    renderChart();
    renderCompare();
    renderLessons();
    initLoop();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
